Q: SwiftUI FetchRequest predicate with data from an ObservedObject causes property initialisers run before self is available A: <p>Here is one way:</p>
<pre><code>extension GroupDetailView {

    init(group: Group) {
        let members = FetchRequest(sortDescriptors: [SortDescriptor(\.firstName)], predicate: group.membersPredicate)
        self.init(members: members)
    }
}

struct GroupDetailView: View {

    @FetchRequest private var members: FetchedResults&lt;GroupMember&gt;

    var body: some View {

    }
}
</code></pre>
<p>Since we aren't supposed to init objects in SwiftUI and NSPredicate is an object, it's implemented as a lazy var in the <code>Group</code> class so it can be reused if this View is init again.</p>
<pre><code>import Foundation
import CoreData

@objc(Group)
public class Group: NSManagedObject {

    lazy var membersPredicate = {
        NSPredicate(format: &quot;group = %@&quot;, objectID)
    }()
}
</code></pre>
